75	function serializeTopLevelOperations(client: Client, db: Drizzle): Drizzle {
76	  const transaction = db.transaction.bind(db);
77	  type TransactionCallback = Parameters<typeof transaction>[0];
78	  type TransactionContext = Parameters<TransactionCallback>[0];
79	
80	  const activeTransaction = new AsyncLocalStorage<TransactionContext>();
81	  let operationQueue = Promise.resolve();
82	
83	  const runSerialized = <T>(operation: () => Promise<T>): Promise<T> => {
84	    const result = operationQueue.then(operation);
85	    operationQueue = result.then(
86	      () => undefined,
87	      () => undefined,
88	    );
89	    return result;
90	  };
91	
92	  const serializeClientMethod = <TArgs extends unknown[], TResult>(
93	    method: (...args: TArgs) => Promise<TResult>,
94	  ) => {
95	    return (...args: TArgs) => {
96	      // The outer transaction already owns the serialized queue. If a helper
97	      // called from that transaction uses the root db handle for a read, queueing
98	      // it behind the outer transaction would deadlock.
99	      if (activeTransaction.getStore()) {
100	        return method(...args);
101	      }
102	      return runSerialized(() => method(...args));
103	    };
104	  };
105	
106	  // better-sqlite3 executed statements synchronously on one connection. libsql opens a
107	  // new logical connection for top-level statements and interactive transactions, so an
108	  // ordinary write started while a transaction owns the write lock fails with SQLITE_BUSY.
109	  client.execute = serializeClientMethod(client.execute.bind(client)) as typeof client.execute;
110	  client.batch = serializeClientMethod(client.batch.bind(client));
111	  client.migrate = serializeClientMethod(client.migrate.bind(client));
112	  client.executeMultiple = serializeClientMethod(client.executeMultiple.bind(client));
