118	      // would deadlock because the outer callback is waiting for the nested promise.
119	      return callback(currentTransaction);
120	    }
121	
122	    return runSerialized(() =>
123	      transaction((tx) => activeTransaction.run(tx, () => callback(tx)), config),
124	    );
125	  }) as typeof db.transaction;
126	
127	  return db;
