/**
 * Test-only helpers for isolating the shared in-memory SQLite database between
 * test modules.
 *
 * libsql opens the in-memory test database with `cache=shared`, which means every
 * connection in the process points at the SAME underlying database. When Vitest
 * resets the module cache, a freshly imported `getDb()` would otherwise reconnect
 * to that shared database and inherit whatever schema/data a prior module left
 * behind. Tracking every client that `getDb()` creates lets us close them all so
 * the shared in-memory database is destroyed once the last connection drops, and
 * a subsequent import produces a genuinely isolated instance.
 */

/** Minimal shape of a database client the registry needs to close. */
type RegisterableClient = {
  close: () => unknown;
  execute: (sql: string) => Promise<unknown>;
};

/** Shape required to reset a client's schema. */
type ResettableClient = {
  close: () => unknown;
  execute: (sql: string) => Promise<{ rows: Array<{ type: string; name: string }> }>;
};

/**
 * Global registry of database clients created during testing. Using a module-level
 * Set is safe because this module is only meant to be imported in test runs; the
 * registry deliberately survives module resets of `src/database/index.ts` so that
 * clients created by prior module instances can still be closed.
 */
const registeredClients = new Set<RegisterableClient>();

/**
 * Register a database client so {@link closeTestDatabaseClients} is aware of it.
 * Called from `getDb()` when `IS_TESTING` is set.
 */
export function registerTestDatabaseClient(client: RegisterableClient): void {
  registeredClients.add(client);
}

/**
 * Close every registered test database client and clear the registry.
 *
 * After this resolves the registry is empty, and once the last connection to the
 * shared in-memory database has closed, re-importing the database module and
 * calling `getDb()` yields a new, fully isolated database instance.
 */
export async function closeTestDatabaseClients(): Promise<void> {
  const clients = Array.from(registeredClients);
  // Clear eagerly so the registry is empty even if a close() throws below.
  registeredClients.clear();

  for (const client of clients) {
    try {
      // libsql's close() is synchronous, but awaiting tolerates async clients too.
      await client.close();
    } catch (err) {
      logger.debug(`Error closing test database client: ${err}`);
    }
  }
}

/** Escape a SQL identifier by wrapping in double-quotes and doubling internal quotes. */
function escapeIdentifier(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/** Map from a queried schema-object type to its DROP keyword. */
const DROP_KEYWORDS: Record<string, string> = {
  table: 'TABLE',
  view: 'VIEW',
  trigger: 'TRIGGER',
};

/**
 * Reset the schema of a database client by dropping all user-created tables,
 * views, and triggers. Indexes are intentionally left untouched (they are dropped
 * implicitly with their table). Regardless of any errors while dropping objects,
 * the final statement executed is exactly `PRAGMA foreign_keys = ON`.
 */
export async function resetTestDatabaseClient(client: ResettableClient): Promise<void> {
  try {
    const result = await client.execute(
      "SELECT type, name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'",
