    for (const { type, name } of result.rows) {
      const keyword = DROP_KEYWORDS[type];
      if (!keyword) {
        // Skips 'index' and any other object types we do not manage.
        continue;
      }
      try {
        await client.execute(`DROP ${keyword} IF EXISTS ${escapeIdentifier(name)}`);
      } catch (err) {
        logger.debug(`Error dropping ${type} "${name}" during test reset: ${err}`);
      }
    }
  } finally {
    // Re-enable foreign key enforcement as the last statement, even on error.
    await client.execute('PRAGMA foreign_keys = ON');
  }
}
